// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address owner;

    function setUp() public {
        c = new SimpleWallet();
        owner = address(this);
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        // contract holds no ether: amount always exceeds address(c).balance
        vm.prank(owner);
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "withdraw above balance must revert");
    }
}
